      description     = EXCLUDED.description,
      category        = EXCLUDED.category,
      subject_default = EXCLUDED.subject_default,
      html_content     = EXCLUDED.html_content,
      variables       = EXCLUDED.variables,
      is_active       = true,
      updated_at      = now();
